diff --git a/selfhost/llvm/text/ownership.slg b/selfhost/llvm/text/ownership.slg
index fa6c764c..146f0622 100644
--- a/selfhost/llvm/text/ownership.slg
+++ b/selfhost/llvm/text/ownership.slg
@@ -3290,6 +3290,13 @@ integerWidth symbol: Int, context: ref emitterContext.EmitContext, state: ref Co
     result! => selected
     selected
 }
+# The i32 console ABI is signed. An unsigned32 value therefore needs the
+# unsigned i64 ABI, while smaller integers retain their ordinary i32 extension.
+integerConsoleWidth width: Int, signed: Bool -> Int {
+    width < 32 -> if { 32 } else {
+        width == 32 and not signed -> if { 64 } else { width }
+    }
+}
 integerSigned symbol: Int, context: ref emitterContext.EmitContext, state: ref CoreEmitterState -> Bool {
     symbol == 2 or symbol == 3 or symbol == 4 or symbol == 5 or symbol == 6 or symbol == 7 or symbol == 12
 }

diff --git a/selfhost/llvm/text/function_calls.slg b/selfhost/llvm/text/function_calls.slg
